    [8518] = {
        achievementId = 8518,
        name = "Master of the Masters",
        source = "Master of the Masters",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Defeat all thirteen opponents across three weekly rotations.",
        acquisition = "Difficulty: Hard - Defeat all thirteen opponents across three weekly rotations.\n\n1. Prepare at least fifteen level-25 pets, preferably a deeper rare-quality roster with spare teams. At Master Li on Timeless Isle 34.8,59.6 accept The Celestial Tournament (33137) and enter the solo scenario. Fifteen is the current entry requirement; the old thirty-pet beta requirement is obsolete.\n\n2. Inspect this week's three trainers. Rotation one is Cho / Dr. Ion Goldbloom / Sully; rotation two is Taran Zhu / Chen / Wrathion; rotation three is Wise Mari / Blingtron 4000 / Kiryn. Change teams between battles, but preserve enough healthy pets for four celestials afterward. Bandages and Revive Battle Pets cannot be used inside; pet healing abilities in combat can.\n\n3. For the trainer round, counter each enemy rather than taking one fixed team to all nine trainers: Undead attacks are strong against Taran Zhu's Humanoids; Humanoid attacks handle Wrathion's Dragonkin; Flying attacks handle Mari's Aquatic fish; Elemental attacks handle Blingtron's Mechanical threats. Watch defensive turns such as Decoy and avoid spending a major hit into them. Rebuild or bring a spare counter after a loss.\n\n4. After three wins, defeat Xu-Fu with Mechanical attacks and avoid Feed healing him; Call Lightning plus multi-hit Mechanical damage is useful. Defeat Zao with Mechanical damage while timing damage/avoidance around Wish and Charge, so a late heal does not undo your burst.\n\n5. Defeat Chi-Chi with Magic damage and avoid wasting strong attacks into Ethereal. Rapana Whelks/snails with Acidic Goo, Ooze Touch and Dive provide an accessible alternative. Defeat Yu'la with Humanoid damage and time Dodge or Deflection for Lift-Off's landing; Clock'em or a suitable Kun-Lai Runt can supply these tools.\n\n6. Win all seven battles within the same scenario attempt. Leaving resets the attempt. Return to Master Li and hand in the weekly quest for one Celestial Coin; on the first win also claim The Rainy Day is Here (33136) for two bonus coins. The first victory therefore buys one three-coin celestial pet immediately.\n\n7. Return in all three weekly rotations and personally defeat all nine named trainers plus Xu-Fu, Zao, Chi-Chi and Yu'la. This takes at least three different rotations; repeating one week's trio does not cover missing trainers. Check individual achievement ticks after battles, since comments report occasional delayed or missing credit.",
        stepCount = 7,
        waypoints = { { mapID = 554, x = 0.348, y = 0.596, step = 1, label = "Master Li - three weekly trainer rotations" } },
        sources = { "https://www.wowhead.com/achievement=8410#comments:id=1903210" },
        wowheadUrl = "https://www.wowhead.com/achievement=8518",
        sourceURL = "https://www.wowhead.com/achievement=8518#comments",
        reviewedAt = "2026-11-13",
    },
    [8519] = {
        achievementId = 8519,
        name = "Celestial Family",
        source = "Celestial Family",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Twelve coins and all four cubs require repeated weekly tournament victories.",
        acquisition = "Difficulty: Hard - Twelve coins and all four cubs require repeated weekly tournament victories.\n\n1. Prepare at least fifteen level-25 pets, preferably a deeper rare-quality roster with spare teams. At Master Li on Timeless Isle 34.8,59.6 accept The Celestial Tournament (33137) and enter the solo scenario. Fifteen is the current entry requirement; the old thirty-pet beta requirement is obsolete.\n\n2. Inspect this week's three trainers. Rotation one is Cho / Dr. Ion Goldbloom / Sully; rotation two is Taran Zhu / Chen / Wrathion; rotation three is Wise Mari / Blingtron 4000 / Kiryn. Change teams between battles, but preserve enough healthy pets for four celestials afterward. Bandages and Revive Battle Pets cannot be used inside; pet healing abilities in combat can.\n\n3. For the trainer round, counter each enemy rather than taking one fixed team to all nine trainers: Undead attacks are strong against Taran Zhu's Humanoids; Humanoid attacks handle Wrathion's Dragonkin; Flying attacks handle Mari's Aquatic fish; Elemental attacks handle Blingtron's Mechanical threats. Watch defensive turns such as Decoy and avoid spending a major hit into them. Rebuild or bring a spare counter after a loss.\n\n4. After three wins, defeat Xu-Fu with Mechanical attacks and avoid Feed healing him; Call Lightning plus multi-hit Mechanical damage is useful. Defeat Zao with Mechanical damage while timing damage/avoidance around Wish and Charge, so a late heal does not undo your burst.\n\n5. Defeat Chi-Chi with Magic damage and avoid wasting strong attacks into Ethereal. Rapana Whelks/snails with Acidic Goo, Ooze Touch and Dive provide an accessible alternative. Defeat Yu'la with Humanoid damage and time Dodge or Deflection for Lift-Off's landing; Clock'em or a suitable Kun-Lai Runt can supply these tools.\n\n6. Win all seven battles within the same scenario attempt. Leaving resets the attempt. Return to Master Li and hand in the weekly quest for one Celestial Coin; on the first win also claim The Rainy Day is Here (33136) for two bonus coins. The first victory therefore buys one three-coin celestial pet immediately.\n\n7. Buy and learn all four cubs from Master Li: Xu-Fu, Zao, Chi-Chi and Yu'la, each for three Celestial Coins. Twelve coins total require ten weekly wins if you claim the first-win two-coin bonus. If the bonus was already spent elsewhere, count your actual coins. Defeating the celestial opponents does not teach the pets, and these cubs cannot be traded as cages.",
        stepCount = 7,
        waypoints = { { mapID = 554, x = 0.348, y = 0.596, step = 1, label = "Master Li - tournament and four celestial pets" } },
        sources = {
            "https://www.wowhead.com/achievement=8519#comments:id=1871405",
            "https://www.wowhead.com/achievement=8410#comments:id=1903210",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=8519",
        sourceURL = "https://www.wowhead.com/achievement=8519#comments",
        reviewedAt = "2026-11-13",
    },
    [8520] = {
        achievementId = 8520,
        name = "Fire in the Hole!",
        source = "Fire in the Hole!",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Superheat and personally stomp six crawler mines before killing Juggernaut.",
        acquisition = "Difficulty: Medium - Superheat and personally stomp six crawler mines before killing Juggernaut.\n\n1. Enter Siege of Orgrimmar beneath the Vale's lake on Normal, Heroic or Mythic as permitted by this achievement's current tooltip. Do a full clear to reach the named boss; the Garrosh skip bypasses earlier encounters. Remove uncontrolled damage before any objective requiring the boss or adds to survive.\n\n2. Pull Iron Juggernaut with no passive damage and keep it alive until Siege Mode. Place yourself by terrain that limits its knockback, and keep a heal or fall-damage tool available for mine stomps.\n\n3. When Cutter Laser follows a player during Siege Mode, lead its beam across crawler mines to superheat them. Right-click the SUPERHEATED mines to stomp/deactivate them. Ordinary unheated mine stomps do not satisfy this objective.\n\n4. Repeat across two or three siege cycles until six superheated stomps are credited. Mine names have failed to update for some players, so watch the actual laser crossing and tracked condition. The launch can cause lethal percentage fall damage even on a high-level character; heal between stomps.\n\n5. Only kill Juggernaut after the six-mine condition is ready. Avoid accidentally phasing or killing it with a reactive-damage talent while waiting.",
        stepCount = 5,
        waypoints = { { mapID = 390, x = 0.74, y = 0.42, step = 1, label = "Siege of Orgrimmar entrance" } },
        sources = {
            "https://www.wowhead.com/achievement=8520#comments:id=6255978",
            "https://www.wowhead.com/achievement=8520#comments:id=6026582",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=8520",
        sourceURL = "https://www.wowhead.com/achievement=8520#comments",
        reviewedAt = "2026-11-13",
    },
    [8521] = {
        achievementId = 8521,
        name = "Swallow Your Pride",
        source = "Swallow Your Pride",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Nobody may gain Pride from Manifestations while Norushen lives.",
        acquisition = "Difficulty: Easy - Nobody may gain Pride from Manifestations while Norushen lives.\n\n1. Enter Siege of Orgrimmar beneath the Vale's lake on Normal, Heroic or Mythic as permitted by this achievement's current tooltip. Do a full clear to reach the named boss; the Garrosh skip bypasses earlier encounters. Remove uncontrolled damage before any objective requiring the boss or adds to survive.\n\n2. Kill Sha of Pride quickly before its large Manifestations can generate Pride. A current high-level character can normally finish before the first relevant add or prison cycle.\n\n3. If deliberately extending the fight, interrupt/stun each Manifestation's Mocking Blast. When it dies, the two nearest players must have Gift of the Titans so its death effect cannot give them Pride. The restriction ends when Norushen dies at the boss's 30% transition, but a clean quick kill is simpler.",
        stepCount = 3,
        waypoints = { { mapID = 390, x = 0.74, y = 0.42, step = 1, label = "Siege of Orgrimmar entrance" } },
        sources = {
            "https://www.wowhead.com/achievement=8521#comments:id=2187304",
            "https://www.wowhead.com/achievement=8521#comments:id=1901421",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=8521",
        sourceURL = "https://www.wowhead.com/achievement=8521#comments",
        reviewedAt = "2026-11-13",
    },
    [8527] = {
        achievementId = 8527,
        name = "Giant Dinosaur vs. Mega Snail",
        source = "Giant Dinosaur vs. Mega Snail",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Needs repeated Thok frenzy transitions and three jailer keys.",
        acquisition = "Difficulty: Hard - Needs repeated Thok frenzy transitions and three jailer keys.\n\n1. Enter Siege of Orgrimmar beneath the Vale's lake on Normal, Heroic or Mythic as permitted by this achievement's current tooltip. Do a full clear to reach the named boss; the Garrosh skip bypasses earlier encounters. Remove uncontrolled damage before any objective requiring the boss or adds to survive.\n\n2. Bring at least FIVE players, including a tank; recent successful groups used the same faction and kept five together in one raid subgroup. Use 10-player Normal for a straightforward setup. Lower the stacked group's health below 50% before pulling, using controllable tools such as Burning Rush rather than damaging Thok.\n\n3. Body-pull Thok and keep the low-health players stacked so he enters the frenzy phase and spawns a Kor'kron Jailer. Kill the jailer; the player with the Skeleton Key debuff goes to the THRICE-LOCKED snail cage in the hallway and opens one lock.\n\n4. Repeat the required frenzy/jailer cycle until three keys have opened all three locks. Preserve Thok throughout; a one-shot prevents the jailers. If transitions fail, check the stacked low-health count, tank role and raid subgroup arrangement rather than continuing to damage him.\n\n5. After the snail is free, kill Thok and let the snail reach and eat his CORPSE. Keep players out of the snail's path and do not kill it. Credit comes after the feast, not merely after opening the cage.",
        stepCount = 5,
        waypoints = { { mapID = 390, x = 0.74, y = 0.42, step = 1, label = "Siege of Orgrimmar entrance" } },
        sources = {
            "https://www.wowhead.com/achievement=8527#comments:id=6390022",
            "https://www.wowhead.com/achievement=8527#comments:id=6117615",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=8527",
        sourceURL = "https://www.wowhead.com/achievement=8527#comments",
        reviewedAt = "2026-11-13",
    },
    [8528] = {
        achievementId = 8528,
        name = "Go Long",
        source = "Go Long",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Needs five distinct players and two hundred yards of transfers in one phase.",
        acquisition = "Difficulty: Hard - Needs five distinct players and two hundred yards of transfers in one phase.\n\n1. Enter Siege of Orgrimmar beneath the Vale's lake on Normal, Heroic or Mythic as permitted by this achievement's current tooltip. Do a full clear to reach the named boss; the Garrosh skip bypasses earlier encounters. Remove uncontrolled damage before any objective requiring the boss or adds to survive.\n\n2. Bring at least FIVE players and arrange them around the Fallen Protectors roughly 35-40 yards apart. Remove gear/passive damage and use Whole-Body Shrinka' before attacks if needed to avoid skipping He Softfoot's phase.\n\n3. Carefully lower He Softfoot to his Desperate Measures threshold around 66% or 33%. Stop damage to the Embodied Anguish add. The player rooted by Mark of Anguish receives an extra action to pass it to another player within range.\n\n4. Pass the Mark around all five UNIQUE players, then keep passing until the cumulative travel exceeds 200 yards in THIS SAME Desperate Measures. Six or seven transfers at 35-40 yards give a margin; four short passes do not meet the distance even if five people have held it.\n\n5. Once the distance/unique-player condition is satisfied, kill the Anguish add and finish the Protectors together. Do not recommend a normal one-character solo route: old multi-client log-in tricks are a cumbersome substitute for five actual participants.",
        stepCount = 5,
        waypoints = { { mapID = 390, x = 0.74, y = 0.42, step = 1, label = "Siege of Orgrimmar entrance" } },
        sources = {
            "https://www.wowhead.com/achievement=8528#comments:id=5912397",
            "https://www.wowhead.com/achievement=8454#comments:id=6284701",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=8528",
        sourceURL = "https://www.wowhead.com/achievement=8528#comments",
        reviewedAt = "2026-11-13",
    },
    [8529] = {
        achievementId = 8529,
        name = "Criss Cross",
        source = "Criss Cross",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "At least two players must each kill only one enemy race.",
        acquisition = "Difficulty: Medium - At least two players must each kill only one enemy race.\n\n1. Enter Siege of Orgrimmar beneath the Vale's lake on Normal, Heroic or Mythic as permitted by this achievement's current tooltip. Do a full clear to reach the named boss; the Garrosh skip bypasses earlier encounters. Remove uncontrolled damage before any objective requiring the boss or adds to survive.\n\n2. Bring at least TWO players. Assign one exclusively to orange Mantid crates and the other exclusively to blue Mogu crates. Avoid green bonus crates and all cross-room cleave; nobody may personally kill both a Mantid and a Mogu.\n\n3. Start Spoils at the central control chest. Each player opens their assigned race's crates, kills the spawned enemies until their room reaches 50 energy and pulls its lever. Wait until BOTH starting rooms are done.\n\n4. Use the room's chain/hook to return upstairs and drop into the other room of YOUR SAME COLOR. Do not walk through the newly opened side door into the opposite race. Clear the second assigned room, reach 50 energy and pull the lever before time expires.\n\n5. When all four rooms finish, verify the achievement. One character clearing every room kills both races and cannot satisfy this condition, regardless of how fast the encounter ends.",
        stepCount = 5,
        waypoints = { { mapID = 390, x = 0.74, y = 0.42, step = 1, label = "Siege of Orgrimmar entrance" } },
