        difficulty = "easy",
        difficultyReason = "Buy and activate the censer once.",
        acquisition = "Difficulty: Easy - Buy and activate the censer once.\n\n1. Collect 1,000 Timeless Coins from island quests, creatures and treasures.\n\n2. Visit Speaker Gulan at 74.9,44.9 and buy Censer of Eternal Agony (102467). Start at full health because activating it inflicts heavy self-damage.\n\n3. Use the censer on Timeless Isle and check the achievement. Heal afterward. Simply purchasing it does not count.",
