    [8724] = {
        achievementId = 8724,
        name = "Pilgrimage",
        source = "Pilgrimage",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Collect four random shrine blessings; duplicates are possible.",
        acquisition = "Difficulty: Easy - Collect four random shrine blessings; duplicates are possible.\n\n1. Find an active Time-Lost Shrine in the forest and ground-level paths of Timeless Isle. Click it to roll a Celestial blessing.\n\n2. Receive each of Niuzao, Yu'lon, Chi-Ji and Xuen at least once. A newer blessing replaces the previous buff; the achievement remembers earlier versions, so they do not need to be active together.\n\n3. Loop between shrines or return after a shrine recharges. A corrupted shrine can give an Ordos result that fills none of the four criteria. Keep checking until every named blessing is complete.",
