    [8725] = {
        achievementId = 8725,
        name = "Eyes On The Ground",
        source = "Eyes On The Ground",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Loot seven distinct kinds of outdoor interactable.",
        acquisition = "Difficulty: Easy - Loot seven distinct kinds of outdoor interactable.\n\n1. Loot a Giant Clam offshore; a reported reliable site is 25.65,14.49, with other sites at 16.7,62.6 and 18.8,20.3. Watch your breath and fatigue. These clams are smaller than their name suggests.\n\n2. Loot Glinting Sand around the shore and a Crane Nest among trees near the central court.\n\n3. Enter the Cavern of Lost Spirits at 43.6,40.7 and loot an Eerie Crystal. Loot Ordon Supplies around Firewalker Ruins.\n\n4. Loot a Firestorm Egg from an elevated eastern ledge; an albatross ride helps with cliff access. Then loot the Fiery Altar of Ordos directly in front of Speaker Gulan at 75.03,44.73. The altar does not require entering Ordos's restricted courtyard.",
