    [8726] = {
        achievementId = 8726,
        name = "Extreme Treasure Hunter",
        source = "Extreme Treasure Hunter",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Complete three different platforming treasure routes.",
        acquisition = "Difficulty: Medium - Complete three different platforming treasure routes.\n\n1. Start at Firewalker Ruins around 51.5,74.7 and jump along the stone pillars to the Gleaming Treasure Chest near 49.7,69.4. Loot it before starting the next route.\n\n2. At the rope route's start near 60.2,45.9, walk along the ropes between pillars and descend to the Rope-Bound Treasure Chest near 54,47.2. Toggle walking or backpedal for the final drop so you do not overshoot the small platform.\n\n3. Click the Gleaming Crane Statue near 58.7,60.1. Its launch and feather effect let you glide toward a floating Mist-Covered Treasure Chest. Interact with one in the air before the effect ends.\n\n4. Check all three criteria. These treasures are weekly per character. If a later chest is invisible, finish the earlier route first and confirm whether you already looted it this reset.",
