    [8727] = {
        achievementId = 8727,
        name = "Where There's Pirates, There's Booty",
        source = "Where There's Pirates, There's Booty",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Loot three weekly pirate treasures, including a keyed underwater chest.",
        acquisition = "Difficulty: Medium - Loot three weekly pirate treasures, including a keyed underwater chest.\n\n1. At the sunken ship south of Old Pi'jiu near 40,92, kill nearby Cursed Hozen Swabbies until you loot the chest key. Swim into the wreck and open Sunken Treasure.\n\n2. Swim to the underwater cave entrance at 17.2,57.3, follow the passage and loot Blackguard's Jetsam. Allow enough breath for the return journey.\n\n3. Board the southeast pirate ship around 71.3,80. Climb up to its wheel, then carefully along the side rope toward the hanging Gleaming Treasure Satchel. Open the satchel on the mast route rather than looking below deck.\n\n4. All three are weekly treasures. Check each criterion and return after the weekly reset only for a treasure already exhausted by that character.",
        stepCount = 4,
        waypoints = {
            { mapID = 554, x = 0.4, y = 0.92, step = 1, label = "Sunken Treasure - wreck and key-dropping swabbies" },
