    [8729] = {
        achievementId = 8729,
        name = "Treasure, Treasure Everywhere",
        source = "Treasure, Treasure Everywhere",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Loot seventeen moss chests and all eight special one-time chests.",
        acquisition = "Difficulty: Medium - Loot seventeen moss chests and all eight special one-time chests.\n\n1. Use a character with unlooted one-time island treasures and leave raid groups before opening them. Each chest has its own permanent quest flag; already opened chests disappear for that character.\n\n2. Loot ANY SEVENTEEN of the thirty-four marked Moss-Covered Chests. You do not need every moss pin. Check stumps, buildings and underwater sites rather than assuming every chest is on the ground.\n\n3. Enter the Cavern of Lost Spirits at 43.6,40.7 and loot the Skull-Covered Chest at interior 62.9,34.8.\n\n4. Loot all FOUR sturdy chests: clifftops above both faction landings, Croaking Hollow and the Mysterious Den. Use an albatross for the clifftops. Find a lost pandaren artifact and use its granted ability to break the den's cave-in.\n\n5. Loot both Smoldering Chests, at Shrine of the Black Flame and Firewalker Ruins.\n\n6. Loot the Blazing Chest in the OUTER western sanctuary court at 47.6,27.6. Reach the outer grounds via an albatross/Ruby Lake descent if the bridge denies access. You do not need to enter Ordos's restricted inner courtyard.\n\n7. Confirm the five category criteria: seventeen moss, one skull, four sturdy, two smoldering and one blazing. The live checklist tracks individual one-time chest flags and directs this character to an unlooted chest.",
        stepCount = 7,
        waypoints = {
            { mapID = 554, x = 0.36700000000000005, y = 0.341, step = 2, label = "Moss-Covered - Three-Breeze Terrace" },
