    [8730] = {
        achievementId = 8730,
        name = "Rolo's Riddle",
        source = "Rolo's Riddle",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Find the random starter, then follow three fixed quest clues.",
        acquisition = "Difficulty: Medium - Find the random starter, then follow three fixed quest clues.\n\n1. Loot Glinting Sand piles along the island's shore until you obtain Rolo's Riddle (102225). Accept quest 32974 from the item; there is no NPC that gives the first quest without the drop.\n\n2. Find the first clue in the dirt at the foot of the stone pillars around 49.4,69.4. Hand in 32974 there and accept the next Rolo's Riddle, 32975.\n\n3. Find the second clue at Three-Breeze Terrace around 34.6,26.7. Hand in and accept the final Rolo's Riddle, 32976.\n\n4. Reach Ruby Lake: near 33.3,55.3 use a NON-damaging taunt or Fruit Basket on a low-flying Highwind Albatross, then stop attacking. Let it carry you to the red lake around 64.5,27.5; kill the bird only over the water.\n\n5. Leave the lake and find the final treasure beside the tree. Complete the final quest to receive the achievement. The quest-progress panel resumes the next unfinished clue rather than sending a partly completed character back to the first sand pile.",
        stepCount = 5,
        waypoints = {
            { mapID = 554, x = 0.25, y = 0.51, step = 1, label = "Glinting Sand - starter search shoreline" },
