    [8743] = {
        achievementId = 8743,
        name = "Zarhym Altogether",
        source = "Zarhym Altogether",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Navigate a five-minute spirit maze and click the final skeleton.",
        acquisition = "Difficulty: Medium - Navigate a five-minute spirit maze and click the final skeleton.\n\n1. Enter the Cavern of Lost Spirits at 43.6,40.7. Find Zarhym, the smoking skull near interior 53,56.9. Inspect the cave's route to the high ledge at the far end before accepting his challenge.\n\n2. Speak to him to enter the spirit world. You have five minutes. Follow the cave inward, avoid the ghosts' detection circles and ascend the final ramp to the highest rock. Skip optional coin chests until you reach the body.\n\n3. Recent Retail comments report some ghosts remain in place and spin. Bring a suitable invisibility effect, Vanish or a combat-drop toy such as Salyin Battle Banner if your class cannot safely pass; use it when needed instead of relying on every ghost patrolling aside.\n\n4. Click Zarhym's sparkling skeleton at interior 53.4,31.5 before the timer expires or a ghost ejects you. Merely reaching the ledge does not complete it. After credit, use spare time on chests.\n\n5. A failed attempt may consume the day's opportunity, especially after looting spirit chests. If Zarhym does not return, retry after the next daily reset rather than assuming you can immediately restart.",
        stepCount = 5,
        waypoints = {
            { mapID = 554, x = 0.436, y = 0.40700000000000003, step = 1, label = "Cavern of Lost Spirits - entrance" },
