    [8784] = {
        achievementId = 8784,
        name = "Timeless Legends",
        source = "Timeless Legends",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Search rare shared artifact spawn points.",
        acquisition = "Difficulty: Medium - Search rare shared artifact spawn points.\n\n1. Search for tiny sparkling lost pandaren artifacts, often resembling small carved heads, on rocks, stumps and ledges. These are temporary clickable world objects, not archaeology solves.\n\n2. Work the marked circuit and click any artifact you find. The four objects SHARE possible spawn sites; a particular pin does not guarantee a particular artifact. Search elevated rocks and the underside of the broken bridge carefully.\n\n3. Collect each named version: Cloudstrike Family Helm, Flameheart Shawl, Riverspeaker's Trident and Snowdrift Tiger Talons. Revisit after respawns until all four criteria are checked; four repeats of one version do not complete it.\n\n4. While an artifact's granted ability is active, you can also use it to break the Mysterious Den's cave-in and reach Spelurk and its sturdy chest.",
        stepCount = 4,
